from lib import *
r=[]
r.append(R(3809,"आसान चिकन एनचिलाडास","दक्षिणी सीमा के स्वाद वाला किडनी-अनुकूल व्यंजन परोसना चाहते हैं? नॉर्थ कैरोलाइना की DaVita आहार विशेषज्ञ जूली मदद के लिए हाज़िर हैं। उनके आसान चिकन एनचिलाडास अपने नाम पर खरे उतरते हैं और बहुत ही स्वादिष्ट होते हैं (muy bueno)। आसान चिकन एनचिलाडास के साथ रात के खाने को उत्सव बना दें।","6","1 एनचिलाडा",
["10 औंस बिना हड्डी और बिना त्वचा वाले चिकन ब्रेस्ट","1 पैकेट कम सोडियम वाला टैको सॉस मिक्स","2/3 कप पानी","1 कप लाल शिमला मिर्च, कटी हुई","6 मक्के की टॉर्टिला, 6” आकार की","6 बड़े चम्मच खट्टी क्रीम (सावर क्रीम)"],
["ओवन या टोस्टर ओवन को पहले से 350° F पर गरम करें।","चिकन को पट्टियों में काटें और मध्यम-तेज़ आँच पर कड़ाही में पकाएँ।","एक छोटे कटोरे में टैको सॉस को 2/3 कप पानी के साथ मिलाएँ।","कड़ाही में लाल शिमला मिर्च और 1/3 कप टैको सॉस डालें और चिकन के बस पकने तक पकाते रहें।","एक उथले बेकिंग डिश की तली पर नॉनस्टिक कुकिंग स्प्रे करें।","एनचिलाडास बनाने के लिए, टॉर्टिला पर चिकन और शिमला मिर्च के मिश्रण का एक बड़ा चम्मच रखें और उसे लपेट दें। लपेटा हुआ आकार बना रहे, इसके लिए हर एनचिलाडा को बेकिंग डिश में अगल-बगल रखें। बचा हुआ टैको सॉस ऊपर से डालें।","एनचिलाडास को 5 से 7 मिनट तक बेक करें, जब तक टॉर्टिला के किनारे हल्के भूरे होने न लगें।","हर एनचिलाडा के ऊपर 1 बड़ा चम्मच खट्टी क्रीम डालें। परोसें और आनंद लें!"],
["पैकेट वाला टैको मसाला मिक्स, डिब्बाबंद या बोतलबंद टैको मसाले की तुलना में पोटैशियम में बहुत कम होता है। इस रेसिपी में Old El Paso ब्रांड का उपयोग किया गया था।","मक्के की टॉर्टिला में फॉस्फोरस की मध्यम मात्रा होती है। ऊपर से पनीर की जगह खट्टी क्रीम डालकर एनचिलाडा में फॉस्फोरस की मात्रा कम रखें।","छोटे परिवार के लिए, आधे बिना पके एनचिलाडास को अलग बेकिंग डिश में रखकर इस रेसिपी को बाँट लें। जितना परोसना हो उतना पकाएँ और दूसरी डिश को अगले दिन के लिए फ्रिज में रख दें। अगले दिन उसे ओवन में 350° F पर 20 से 25 मिनट तक गरम करें।"],
["1-1/2 मांस","1 स्टार्च","1/2 सब्जी, कम पोटैशियम"]))
r.append(R(3810,"वनीला मिंट पॉपकॉर्न","इस पॉपकॉर्न में स्वादों का अनोखा मेल है। इस साबुत अनाज वाले किडनी-अनुकूल नाश्ते का आनंद लें।","5-6","1 कप",
["1/4 कप बिना फूले पॉपकॉर्न के दाने","1/2 छोटा चम्मच ताज़ा पुदीना","1 बड़ा चम्मच जैतून का तेल","1 छोटा चम्मच वनीला एक्सट्रैक्ट","1 बड़ा चम्मच चीनी","1 भूरा पेपर लंच बैग (वैकल्पिक)"],
["पॉपकॉर्न के दाने भूरे बैग में डालें। माइक्रोवेव में 2-3 मिनट तक पकाएँ, जब तक बैग से केवल कुछ ही आवाज़ें आ रही हों। पॉपकॉर्न को ज़्यादा न पकाएँ, नहीं तो वह जल जाएगा।","पुदीने की पत्तियों को लपेटकर बारीक काट लें या कुचल लें। एक छोटे सॉसपैन में जैतून का तेल, वनीला, चीनी और पुदीना मिलाएँ। हल्का उबाल आने दें और ध्यान रखें कि सारी चीनी घुल जाए। पॉपकॉर्न को कटोरे में डालें, उस पर यह मिश्रण डालें और चलाएँ या उछालकर मिलाएँ।"],
["अगर आपके पास माइक्रोवेव नहीं है, तो पॉपकॉर्न को चूल्हे पर बड़े बर्तन में भी बना सकते हैं। बर्तन में 1 बड़ा चम्मच जैतून का तेल और डालें। ढककर मध्यम से तेज़ आँच पर तब तक रखें जब तक पॉपकॉर्न फूटना बंद न हो जाए।","अगर पुदीने की पत्तियाँ उपलब्ध न हों, तो 1/2 छोटा चम्मच पुदीना एक्सट्रैक्ट का उपयोग करें।"],
["1/2 स्टार्च","1/2 वसा"]))
r.append(R(3812,"कैरिबियन करी टर्की","अपने अगले किडनी-अनुकूल भोजन को कैरिबियन करी टर्की से और लज़ीज़ बनाएँ। बनाने में आसान और खाने में आनंददायक।","8","3 औंस",
["3-1/2 पाउंड टर्की ब्रेस्ट, त्वचा के साथ, हड्डी सहित","1/4 कप मक्खन, पिघला हुआ","1/4 कप शहद","1 बड़ा चम्मच सरसों","2 छोटे चम्मच करी पाउडर","1 छोटा चम्मच लहसुन पाउडर"],
["टर्की ब्रेस्ट को त्वचा वाला हिस्सा ऊपर करके एक उथली रोस्टिंग पैन में रैक पर रखें। मीट थर्मामीटर को टर्की ब्रेस्ट के सबसे मोटे हिस्से के बीच में लगाएँ।","350° F पर तब तक बेक करें जब तक थर्मामीटर 170° F तक न पहुँच जाए (लगभग 1-1/2 घंटे)।","मक्खन, शहद, सरसों, करी पाउडर और लहसुन पाउडर को मिलाएँ। पकने के आख़िरी 30 मिनट में टर्की पर इस ग्लेज़ को कई बार ब्रश से लगाएँ।","टर्की को पैन से निकालें और काटने से पहले 15 मिनट रखा रहने दें।"],
["कटी हुई टर्की को अलग-अलग सर्विंग में बाँटकर फ्रिज में या फ्रीज़र में रख लें, ताकि बाद में जल्दी भोजन तैयार हो सके।","अगर आप अधिक या कम प्रोटीन वाला आहार ले रहे हैं, तो अपनी भोजन योजना के अनुसार टर्की की मात्रा समायोजित करें।"],
["3-1/2 मांस","1/2 उच्च कैलोरी"]))
r.append(R(3814,"कद्दू और क्रैनबेरी ब्रेड","कद्दू और क्रैनबेरी ब्रेड की यह स्वादिष्ट, किडनी-अनुकूल रेसिपी ठंडे मौसम के त्योहारों पर ख़ास तौर पर मज़ेदार होती है, और ऊपर रिबन लगाकर फ़ॉइल में लपेटने पर यह एक बढ़िया उपहार भी बनती है।","20","1 स्लाइस, 3/4\" मोटा",
["2-1/2 कप मैदा (ऑल-पर्पज़ फ़्लोर)","2 छोटे चम्मच पंपकिन पाई मसाला","2 छोटे चम्मच बेकिंग पाउडर","2 बड़े अंडे","2 कप चीनी","1-3/4 कप डिब्बाबंद कद्दू की प्यूरी","1/2 कप वनस्पति तेल","1 कप ताज़े या जमे हुए साबुत क्रैनबेरी"],
["ओवन को पहले से 350° F पर गरम करें।","एक बड़े कटोरे में मैदा, पंपकिन पाई मसाला और बेकिंग पाउडर मिलाएँ।","एक छोटे कटोरे में अंडे, चीनी, कद्दू की प्यूरी और तेल मिलाएँ। मिल जाने तक फेंटें।","कद्दू का मिश्रण मैदे के मिश्रण में डालें। बस नम होने तक चलाएँ, फिर क्रैनबेरी को धीरे से मिलाएँ।","घोल को चम्मच से 2 चिकनाई लगे 9″ x 5″ लोफ़ पैन में डालें। 55 से 60 मिनट तक बेक करें।","पैन को ओवन से निकालें और 5 से 10 मिनट ठंडा होने दें। लोफ़ को पैन से निकालें और हर लोफ़ को 10 स्लाइस में काटने से पहले तार की जाली पर ठंडा करें।"],
["अतिरिक्त ब्रेड बनाएँ और लोफ़ को फ्रीज़ कर लें। परोसने से कुछ घंटे पहले उन्हें पिघलने दें।","अगर क्रैनबेरी उपलब्ध न हों, तो उन्हें रेसिपी से हटा दें या उनकी जगह ब्लूबेरी का उपयोग करें।"],
["1-1/2 स्टार्च","1 वसा","1/2 उच्च कैलोरी"]))
r.append(R(3820,"टैको पास्ता सलाद","सादे पास्ता को मैक्सिकन स्वाद का रोमांच बना दें। टैको पास्ता सलाद पास्ता सलाद को एक चटपटा नया रूप देता है। इस किडनी-अनुकूल सलाद को सलाद पत्तों की परत पर परोसें या चलते-फिरते स्वादिष्ट नाश्ते के लिए रैप में भरें।","8","1 कप पास्ता सलाद, 1 कप सलाद पत्ते",
["12 औंस पेने पास्ता, बिना पका","1 बड़ी लहसुन की कली","2 हरे प्याज़","1/2 कप लाल शिमला मिर्च","8 कप आइसबर्ग लेट्यूस","1/2 कप खट्टी क्रीम (सावर क्रीम)","1/2 कप सालसा","2 बड़े चम्मच तीखा टैको सॉस","1/2 कप डिब्बाबंद कटी हरी मिर्च","2 बड़े चम्मच कटे काले जैतून","1/2 कप कद्दूकस किया हुआ मैक्सिकन चीज़"],
["पैकेट पर दिए निर्देशों के अनुसार पास्ता पकाएँ, नमक न डालें। छानकर ठंडा होने तक धोएँ।","लहसुन बारीक काटें; हरे प्याज़ को स्लाइस करें; शिमला मिर्च काटें; लेट्यूस को बारीक काटें।","एक छोटे कटोरे में खट्टी क्रीम और सालसा मिलाएँ। इसे पास्ता में मिला दें।","पास्ता में तीखा टैको सॉस, लहसुन, हरी मिर्च और जैतून डालकर मिलाएँ।","पास्ता के मिश्रण के ऊपर हरा प्याज़ और शिमला मिर्च बुरकें। ढककर ठंडा होने के लिए फ्रिज में रखें।","परोसने से पहले, चाहें तो पास्ता सलाद के ऊपर चीज़ बुरकें (वैकल्पिक)। हर सर्विंग के लिए, सलाद की प्लेट में 1 कप कटा हुआ लेट्यूस रखें। लेट्यूस की परत के ऊपर 1 कप टैको पास्ता सलाद रखें।"],
["डिब्बाबंद या बोतलबंद तीखा टैको सॉस ढूँढें।","लेबल की तुलना करें और सालसा, हरी मिर्च, जैतून और टैको सॉस के वे ब्रांड चुनें जिनमें सोडियम सबसे कम हो।","क्वेसो अनेखो (queso anejo) ढूँढें, यह एक मैक्सिकन चीज़ है जो आसानी से भुरभुरा जाता है। अगर उपलब्ध न हो, तो \"Mexican\" लिखा कद्दूकस किया हुआ चीज़ खरीदें। चीज़ और जैतून वैकल्पिक हैं।","फ़्लैटब्रेड या आटे की टॉर्टिला के अंदर लेट्यूस के साथ टैको पास्ता सलाद भरकर रैप बनाएँ।"],
["2 स्टार्च","1 सब्जी, मध्यम पोटैशियम","1 वसा"]))
r.append(R(3823,"सेलेरी सीड ड्रेसिंग","स्वाद से भरपूर और सोडियम, पोटैशियम तथा फॉस्फोरस में कम, सेलेरी सीड ड्रेसिंग किडनी आहार के लिए एकदम सही है। इसे बनाना आसान है और एक सर्विंग की लागत बहुत कम आती है।","8","2 बड़े चम्मच",
["1/2 कप कैनोला तेल","1/4 कप चीनी","1/4 कप सेब का सिरका","1/2 बड़ा चम्मच अजवायन के बीज (सेलेरी सीड्स)","1/2 छोटा चम्मच सूखी सरसों"],
["सामग्री को ढक्कन वाले जार में डालें और अच्छी तरह हिलाकर मिलाएँ।","इसे सलाद के ऊपर परोसें या कोलस्लॉ की ड्रेसिंग के रूप में उपयोग करें।"],
["स्वाद बदलने के लिए तेल, सिरके और मिठास के प्रकार बदलकर देखें।"],
["3 वसा","1/2 उच्च कैलोरी"]))
r.append(R(3824,"स्लो कुकर दालचीनी बन व्हाइट हॉट चॉकलेट","DaVita की आहार विशेषज्ञ डेनिस छुट्टियों के उपहार के रूप में अपने मरीज़ों और साथियों को स्लो कुकर दालचीनी बन व्हाइट हॉट चॉकलेट परोसती हैं और उन्हें यह बहुत पसंद आती है! दालचीनी की धीमी आँच पर पकने से इसका स्वाद बहुत अच्छा हो जाता है, जबकि दूध और राइस मिल्क का मेल पोटैशियम और फॉस्फोरस को किडनी-अनुकूल सीमा में रखता है।","10","6 औंस (3/4 कप)",
["4 कप राइस मिल्क","4 कप 2% कम वसा वाला दूध","8 छोटे चम्मच पिसी दालचीनी","1/2 कप Torani® शुगर-फ़्री व्हाइट चॉकलेट सिरप","1/4 कप दानेदार ब्राउन शुगर और सुक्रालोज़ का मिश्रण","4 छोटे चम्मच वनीला एक्सट्रैक्ट","10 बड़े चम्मच मार्शमैलो फ़्लफ़","10 छोटे चम्मच शुगर-फ़्री कैरेमल सिरप"],
["दूध और राइस मिल्क को 3 क्वार्ट के क्रॉक पॉट में डालें। दालचीनी डालें।","ढककर धीमी आँच (लो सेटिंग) पर करें। दूध में दालचीनी का स्वाद उतारने के लिए 1-1/2 से 2 घंटे पकाएँ।","व्हाइट चॉकलेट सिरप, ब्राउन शुगर का मिश्रण, वनीला और चाहें तो और दालचीनी डालें। ढककर 30-45 मिनट और पकने दें।","हर सर्विंग के लिए 6 औंस एक छोटे कॉफ़ी कप में डालें और ऊपर 1 बड़ा चम्मच मार्शमैलो फ़्लफ़ और शुगर-फ़्री कैरेमल सिरप की धार से सजाएँ।"],
["अगर आप प्रोटीन का सेवन बढ़ाना चाहते हैं, तो दूध के मिश्रण में 1/2 कप व्हे प्रोटीन पाउडर या आपके आहार विशेषज्ञ द्वारा सुझाया गया कोई अन्य प्रोटीन सप्लीमेंट मिलाएँ।","अगर आपको अधिक कैलोरी चाहिए, तो शुगर-फ़्री की जगह सामान्य सिरप का उपयोग कर सकते हैं।"],
["1 दूध","1 दूध का विकल्प","1/2 उच्च कैलोरी"]))
r.append(R(3827,"शुगर एंड स्पाइस पॉपकॉर्न","चीनी और मसाले लगभग हर अच्छी चीज़ के मुख्य अंग होते हैं, इसीलिए मिसौरी की DaVita आहार विशेषज्ञ सुज़ेट ने अपने झटपट बनने वाले, किडनी-अनुकूल शुगर एंड स्पाइस पॉपकॉर्न में इन्हें ख़ास जगह दी है।","4","2 कप",
["8 कप एयर-पॉप किया हुआ पॉपकॉर्न","2 बड़े चम्मच बिना नमक का मक्खन","2 बड़े चम्मच चीनी","1/2 छोटा चम्मच दालचीनी","1/4 छोटा चम्मच जायफल"],
["मक्खन, चीनी, दालचीनी और जायफल को चूल्हे पर सॉसपैन में तब तक गरम करें जब तक मक्खन पिघल न जाए और चीनी घुल न जाए। चाहें तो सामग्री को माइक्रोवेव-सुरक्षित कटोरे में माइक्रोवेव कर लें। ध्यान रखें कि मक्खन जले नहीं।","मसालेदार मक्खन का मिश्रण फूले हुए पॉपकॉर्न पर डालें; अच्छी तरह मिलाएँ।","सबसे अच्छे स्वाद के लिए तुरंत परोसें।"],
["अगर आपके पास एयर-पॉपर नहीं है, तो बिना नमक वाले माइक्रोवेव पॉपकॉर्न का 1 बैग पॉप करके उपयोग करें। इसमें वसा की मात्रा अधिक होगी।"],
["1 स्टार्च","1 वसा"]))
r.append(R(3829,"बफ़ेलो फूलगोभी","यह ऐपेटाइज़र एक बहुमुखी सब्जी में तेज़ स्वाद भर देता है।","12","1/2 कप",
["1 बड़ी फूलगोभी (3 पाउंड वज़न की)","2 बड़े चम्मच जैतून का तेल","2 छोटे चम्मच लहसुन पाउडर","1 छोटा चम्मच प्याज़ पाउडर","1/2 छोटा चम्मच काली मिर्च","2 बड़े चम्मच कॉर्नस्टार्च","1/4 कप हॉट सॉस","2 बड़े चम्मच बिना नमक का मक्खन","1 बड़ा चम्मच ताज़ा अजमोद (पार्सले), वैकल्पिक"],
["ओवन को 425 F पर पहले से गरम करें। बड़ी बेकिंग शीट पर बेकिंग पेपर (पार्चमेंट पेपर) बिछाएँ (फ़ॉइल नहीं)।","फूलगोभी को 2 से 3 इंच के बड़े फूलों में काटें। कटी हुई फूलगोभी को बड़े कटोरे में रखें और जैतून का तेल, लहसुन पाउडर, प्याज़ पाउडर, काली मिर्च और कॉर्नस्टार्च डालें। बराबर लिपटने तक उछालकर मिलाएँ।","इसे बेकिंग शीट पर बराबर फैलाएँ। फूलगोभी को ओवन में रखें और 20 मिनट भूनें। निकालें, उछालकर मिलाएँ और सुनहरा रंग आने तथा काँटा आसानी से धँसने तक 10 मिनट और भूनें।","ओवन-सुरक्षित पैन में मक्खन पिघलाएँ। पिघलने पर हॉट सॉस डालकर मिलाएँ। फूलगोभी को सॉस के मिश्रण वाले पैन में डालकर मिलाएँ।","मिल जाने पर पैन को ओवन में रखें और फूलगोभी पर जगह-जगह छाले जैसे दाग़ आने तक 10 मिनट और बेक करें।","ओवन से निकालें और ताज़े अजमोद से सजाएँ। आनंद लें!"],
["अगर पहले से कटे फूल खरीद रहे हैं, तो ऐसा बैग चुनें जिसमें लगभग 6 कप फूल हों।","अगर आपके पास ओवन-सुरक्षित पैन नहीं है, तो पिघला हुआ मक्खन और हॉट सॉस एक कटोरे में डालें और पकी हुई फूलगोभी उसमें मिलाएँ। फिर उसे उसी बेकिंग शीट पर वापस ओवन में रखें जिस पर फूलगोभी भूनी थी।","फूलगोभी मध्यम पोटैशियम वाली सब्जी है; अन्य पोटैशियम दूसरी सामग्री से आता है, लेकिन नए शोध से हमें पता चल रहा है कि फूलगोभी जैसे साबुत खाद्य से हमारा शरीर सारा पोटैशियम अवशोषित नहीं करता।","इस रेसिपी का परीक्षण Frank’s® हॉट सॉस के साथ किया गया था। ऐसी किस्म चुनें जिसमें सोडियम सबसे कम हो।"],
["1 सब्जी, मध्यम पोटैशियम","1 वसा"]))
r.append(R(3831,"शानदार टैकोज़","इन शानदार टैकोज़ के साथ टैको नाइट मनाएँ। बनाने में आसान और छोड़ने में मुश्किल, इन बीफ़ टैकोज़ में उत्सव जैसा पूरा स्वाद है, और ये प्री-डायलिसिस, डायलिसिस तथा मधुमेह वाले डायलिसिस किडनी आहार के लिए अनुशंसित हैं।","6","1 टैको",
["6 मक्के के टैको शेल","1/2 पाउंड कम चर्बी वाला बीफ़ कीमा","1 बड़ा चम्मच कैनोला तेल","1 कप प्याज़, कटा हुआ (बँटा हुआ उपयोग)","1 लहसुन की कली, बारीक कटी हुई","1 छोटा चम्मच चिली पाउडर","1/2 छोटा चम्मच काली मिर्च","1/4 छोटा चम्मच पिसा जीरा","1/4 छोटा चम्मच Tabasco® सॉस","3/4 कप लेट्यूस, बारीक कटा हुआ","6 बड़े चम्मच टमाटर, कटा हुआ","6 बड़े चम्मच तीखा चेडर चीज़, कद्दूकस किया हुआ"],
["एक बड़ी फ्राइंग पैन में बीफ़ कीमा को मध्यम आँच पर भूरा होने तक पकाएँ। अच्छी तरह छान लें, पैन से निकालकर अलग रख दें।","पैन में तेल गरम करें। 1/2 कप कटा प्याज़ डालें और पारदर्शी होने तक पकाएँ। लहसुन डालें, एक मिनट पकाएँ और चलाते रहें।","पका हुआ कीमा वापस पैन में डालें। चिली पाउडर, काली मिर्च, जीरा और Tabasco® सॉस मिलाएँ। आँच से उतारें और टैकोज़ तैयार करें।","हर टैको शेल के अंदर 1/4 कप मांस का मिश्रण भरें। ऊपर 2 बड़े चम्मच लेट्यूस, और टमाटर, चीज़ तथा बचे हुए प्याज़ में से हर एक का 1 बड़ा चम्मच डालें।"],
["ऐसा चीज़ चुनें जिसके पैकेट पर \"natural\" (प्राकृतिक) शब्द लिखा हो। प्रोसेस्ड चीज़ से बचें, क्योंकि उसमें सोडियम और फॉस्फोरस अधिक होता है।"],
["1 मांस","1 स्टार्च","1/2 सब्जी, कम पोटैशियम","1-1/2 वसा"]))
r.append(R(3839,"ए-मेज़-इंग बीन डिप","ए-मेज़-इंग बीन डिप एक आसानी से बनने वाला ऐपेटाइज़र है जो किडनी आहार में फ़िट बैठता है। चेहरे पर मुस्कान लाने के लिए बस एक पिटा चिप उठाएँ और इस स्वादिष्ट ऐपेटाइज़र का आनंद लें।","36","1-1/2\" x 1-1/2\" का चौकोर टुकड़ा",
["1/2 बड़ा लाल प्याज़","1 हरी शिमला मिर्च","1 लाल शिमला मिर्च","1/3 कप ताज़ा धनिया","2-1/2 कप सफ़ेद हॉमिनी, डिब्बाबंद या ताज़ा पकाई हुई","1 कप राजमा की किस्म पिंटो बीन्स, ताज़ा पकाई हुई","8 औंस कम वसा वाला क्रीम चीज़","1/4 कप जैतून का तेल","3 लहसुन की कलियाँ","1 बड़ा चम्मच पिसा जीरा","1/4 छोटा चम्मच चिली पाउडर","12 औंस कम वसा वाली खट्टी क्रीम (सावर क्रीम)","1 नींबू (लाइम)"],
["प्याज़, शिमला मिर्च और धनिया काटें।","फ़ूड प्रोसेसर में ये सामग्री पीस लें: हॉमिनी, पिंटो बीन्स, कम वसा वाला क्रीम चीज़, जैतून का तेल, लहसुन की 2 कलियाँ, जीरा और वैकल्पिक चिली पाउडर। इसे 9″ x 9″ के पैन में फैलाएँ।","स्पैचुला से बीन के मिश्रण पर खट्टी क्रीम की परत लगाएँ।","कड़ाही में हल्का भूनें: लाल प्याज़, हरी और लाल शिमला मिर्च और लहसुन की 1 कली। ज़्यादा न पकाएँ ताकि शिमला मिर्च कुरकुरी रहे, गलकर नरम न हो।","अतिरिक्त स्वाद के लिए भुने हुए शिमला मिर्च और प्याज़ के मिश्रण पर नींबू निचोड़ें, फिर अतिरिक्त तरल निकाल दें।","शिमला मिर्च का मिश्रण खट्टी क्रीम के ऊपर चम्मच से डालें और डिप के पूरी तरह ढक जाने तक बराबर करें।"],
["टैकोज़ बनाते समय डिप को आटे की टॉर्टिला पर परोसें, या डुबोने के लिए घर पर बने आटे के टॉर्टिला चिप्स या पिटा चिप्स के साथ परोसें।","डिब्बाबंद बीन्स की जगह भिगोए हुए ताज़े पिंटो बीन्स का उपयोग करने से डिप में सोडियम की मात्रा काफ़ी कम हो जाती है।","बीन्स में पोटैशियम और फॉस्फोरस अधिक होता है। यह रेसिपी बताती है कि बीन्स की थोड़ी मात्रा शामिल करके भी अपने किडनी आहार में इन खनिजों को कैसे सीमित रखा जा सकता है।"],
["1 सब्जी, कम पोटैशियम","1 वसा"]))
r.append(R(3840,"आयरिश पब स्टफ़्ड शिमला मिर्च","सेंट पैट्रिक दिवस के लिए कोई ख़ास किडनी-अनुकूल रेसिपी ढूँढ रहे हैं? आयरिश पब स्टफ़्ड आलू (Irish Pub Stuffed Potatoes) में शेफ़र्ड्स पाई की भरावन को शिमला मिर्च की नाव में बेक किया जाता है और ऊपर फेंटे हुए आलू डाले जाते हैं (जिन्हें पोटैशियम नियंत्रित रखने के लिए दो बार उबाला जाता है)।","8","1/2 भरी हुई शिमला मिर्च",
["4 मध्यम हरी शिमला मिर्च","1 पाउंड बीफ़ कीमा, 10% वसा वाला","2 बड़े चम्मच कॉर्नस्टार्च","2 बड़े चम्मच ठंडा पानी","2 कप कम सोडियम वाला बीफ़ शोरबा (ब्रॉथ)","2 बड़े चम्मच कम सोडियम वाला वॉर्सेस्टरशायर सॉस","1-1/2 छोटे चम्मच इंस्टेंट कॉफ़ी पाउडर, सूखा","2 कप जमी हुई मिली-जुली सब्जियाँ (गाजर, मक्का, फ्रेंच बीन्स, मटर)","2 कप सफ़ेद आलू","1 बड़ा चम्मच मक्खन","3 बड़े चम्मच हाफ़ एंड हाफ़ (आधा दूध, आधा क्रीम)"],
["ओवन को 350° F पर पहले से गरम करें।","आलू छीलें और छोटे टुकड़ों में काटें।","शिमला मिर्च की डंडी लगी रहने दें और डंडी से तली तक बीच से आधा काटें। चम्मच से बीज और भीतरी झिल्ली निकाल दें। नॉनस्टिक कुकिंग स्प्रे लगी बेकिंग शीट पर रखें।","कॉर्नस्टार्च को ठंडे पानी में मिलाएँ और गुठलियाँ न रहने तक चलाएँ।","एक सॉसपैन में बीफ़ शोरबा, वॉर्सेस्टरशायर सॉस और कॉफ़ी पाउडर मिलाएँ। घुला हुआ कॉर्नस्टार्च डालें और मध्यम आँच पर गाढ़ा होने तक चलाते रहें।","कड़ाही में बीफ़ कीमे को चूरकर मध्यम आँच पर भूरा होने तक पकाएँ। मिली-जुली सब्जियाँ डालें, चलाएँ और बीफ़ के साथ गरम होने तक पकाएँ। ग्रेवी को बीफ़ और सब्जियों के मिश्रण में मिला दें।","हर शिमला मिर्च के आधे हिस्से में 1/2 कप बीफ़ का मिश्रण भरें। ओवन में रखें और बिना ढके 40 मिनट बेक करें।","जब शिमला मिर्च बेक हो रही हो, तब कम पोटैशियम वाले आलू तैयार करें। कटे हुए आलू को बर्तन में रखें और 6 कप पानी डालें; उबाल आने दें। आँच से उतारें और पानी निथार दें। ताज़ा पानी डालें और आलू के नरम होने तक उबालें।","हैंड मिक्सर से आलू को मक्खन या मार्जरीन और नॉन-डेयरी क्रीमर या हाफ़ एंड हाफ़ के साथ फेंट लें।","शिमला मिर्च को ओवन से निकालें। हर भरी हुई शिमला मिर्च के आधे हिस्से पर 1/4 कप फेंटे हुए आलू फैलाएँ और परोसें।"],
["चाहें तो परोसने से पहले थोड़ा सा Tabasco® सॉस या कम सोडियम वाला वॉर्सेस्टरशायर सॉस डालें।","एक छोटे चम्मच कम सोडियम वाले वॉर्सेस्टरशायर सॉस में 45 मिग्रा सोडियम होता है।","चाहें तो बीफ़ की जगह मेमना या टर्की का कीमा इस्तेमाल करें।","चाहें तो मक्खन की जगह मार्जरीन या हाफ़ एंड हाफ़ की जगह नॉन-डेयरी क्रीमर इस्तेमाल करें।"],
["2 मांस","1/2 स्टार्च","2 सब्जियाँ, कम पोटैशियम"]))
r.append(R(3846,"ग्रिल्ड मैरिनेटेड चिकन","किडनी-अनुकूल ग्रिल्ड मैरिनेटेड चिकन एक शानदार मुख्य व्यंजन है जो किसी भी सलाद के साथ खूब जमता है। अगर आप चिकन को पहले शुरू कर दें, तो वह तब तक मैरिनेट हो सकता है जब तक आप साइड डिश या सलाद बनाते हैं। या फिर चिकन को ज़िपर बैग में रखकर रात भर मैरिनेट होने दें। जो भी तरीका आपके समय के हिसाब से सबसे सुविधाजनक हो, वही अपनाएँ!","4","1 चिकन ब्रेस्ट (2 फ़िले)",
["4 बिना हड्डी और बिना त्वचा वाले चिकन ब्रेस्ट","1 लहसुन की कली","1/4 कप जैतून का तेल","1/4 कप रेड वाइन विनेगर","1 छोटा चम्मच प्याज़ पाउडर","1-1/2 छोटे चम्मच सूखा इतालवी सीज़निंग मिश्रण","1/2 छोटा चम्मच सूखा थाइम","ताज़ा थाइम की टहनियाँ (वैकल्पिक)"],
["चिकन ब्रेस्ट को आड़ा बीच से आधा काटें, ताकि हर ब्रेस्ट से दो पतले फ़िले बनें।","लहसुन को बारीक काटें और बाकी सामग्री के साथ ज़िप-टॉप बैग में मिलाएँ; अच्छी तरह मिलाएँ।","चिकन के फ़िले बैग में डालें। बंद करके फ्रिज में 2 घंटे या उससे ज़्यादा देर मैरिनेट करें, बीच-बीच में पलटते रहें।","चिकन को मैरिनेड से निकालें और मध्यम आँच पर ग्रिल करें, एक बार पलटें, जब तक चिकन पक न जाए। अगर मीट थर्मामीटर का उपयोग कर रहे हैं, तो तापमान 165º F तक पहुँचना चाहिए। चाहें तो ग्रिल करते समय चिकन के ऊपर ताज़ा थाइम की टहनियाँ रखें।"],
["ग्रिल करने के लिए बहुत ठंड है? चिकन पकाने के लिए अपने ब्रॉइलर का उपयोग करें।","अगर आप कम प्रोटीन वाला आहार ले रहे हैं, तो मात्रा घटाकर 1 फ़िले या अपनी भोजन योजना में बताई गई मात्रा तक कर सकते हैं।"],
["3-1/2 मांस"]))
r.append(R(3847,"सोल एन पापियोट (कागज़ में सोल मछली)","अलबामा की DaVita आहार विशेषज्ञ क्रिस्टी की ओर से एक स्वस्थ, लज़ीज़ और किडनी-अनुकूल भोजन का आनंद लें। सोल एन पापियोट (कागज़ में सोल मछली) मछली और सब्जियों का पूरा भोजन एक छोटी-सी पोटली में बनाने का एक शानदार तरीका है।","4","1 फ़िले और 3/4 कप सब्जियाँ",
["1 पाउंड सोल मछली के फ़िले, कच्चे","2 छोटे चम्मच काली मिर्च","2 छोटे चम्मच सूखी तुलसी की पत्तियाँ","4 छोटे चम्मच बिना नमक का मक्खन","40 ताज़ी फ्रेंच बीन्स (स्नैप बीन्स)","1/2 कप पीली शिमला मिर्च","1/2 कप हरी शिमला मिर्च","1/2 कप लाल प्याज़","4 लहसुन की कलियाँ","2 ताज़े नींबू","एल्युमिनियम फ़ॉइल या बेकिंग पेपर (पार्चमेंट पेपर)"],
["ओवन को 350° F पर पहले से गरम करें।","पार्चमेंट पेपर (पापियोट) में बनाने के लिए, पार्चमेंट पेपर को आधा मोड़ें और बड़े \"आधे दिल\" के आकार में काट लें। (याद है स्कूल में वैलेंटाइन कार्ड बनाना?)","कागज़ को खोलें और एक फ़्लाउंडर फ़िले को दिल के आकार वाले पार्चमेंट पेपर के एक तरफ़ त्वचा वाला हिस्सा नीचे करके रखें, किनारों के चारों ओर इतनी जगह छोड़ें कि पूरी तरह सील हो सके। हर फ़िले पर 1/2 छोटा चम्मच पिसी काली मिर्च और 1/2 छोटा चम्मच तुलसी की पत्तियाँ डालें। हर फ़िले के ऊपर एक छोटा चम्मच बिना नमक का मक्खन रखें। मछली को अलग रख दें।","फ्रेंच बीन्स के सिरे काटें। बीन्स को हल्का उबाल लें (पारबॉइल); अलग रख दें।","शिमला मिर्च से बीज निकालें। शिमला मिर्च और प्याज़ को बारीक काटें। लहसुन की कलियाँ बारीक काटें।","पीली और हरी शिमला मिर्च, प्याज़ और लहसुन को एक कटोरे में मिलाएँ। नींबू का रस कटोरे में निचोड़ें। अच्छी तरह मिलाएँ। लगभग 1/4 मिश्रण हर फ़िले के ऊपर चम्मच से डालें। हर फ़िले के चारों ओर 10 बीन्स रखें।","पार्चमेंट पेपर बंद करने के लिए, दिल के आकार के दूसरे हिस्से को सामग्री के ऊपर मोड़ें और किनारों को मोड़कर चिपका दें ताकि बंद हो जाए। पोटली के अंदर भाप के फैलाव के लिए कुछ जगह छोड़ना न भूलें, जो मछली के बेक होने के दौरान होगा। सुनिश्चित करें कि यह हवा-बंद हो।","12 मिनट तक या मछली के काँटे से आसानी से टूटने तक बेक करें। पकने के बाद, कागज़ के ऊपर U-आकार में काटें और परोसने के लिए मोड़कर खोलें।"],
["अगर पार्चमेंट पेपर उपलब्ध न हो, तो फ़ॉइल का उपयोग करें।","40 ताज़ी फ्रेंच बीन्स, 2” के टुकड़ों में काटने पर, 2 कप के बराबर होती हैं।","पारबॉइल का अर्थ है थोड़े समय के लिए उबालकर आंशिक रूप से पकाना।","फ्रेंच बीन्स की जगह कोई भी सब्जी इस्तेमाल की जा सकती है, जैसे: लंबी पतली कटी पीली स्क्वैश, तोरी (ज़ुकीनी), गाजर, स्नो पीज़ आदि। फ्रेंच बीन्स और स्नो पीज़ जैसी मोटी, सख़्त सब्जियों को मछली के साथ भाप में पकाने से पहले पारबॉइल करना ज़रूरी है ताकि वे अच्छी तरह पक जाएँ। स्क्वैश जैसी नरम सब्जियों को बिना पारबॉइल किए भी इस्तेमाल किया जा सकता है।","सोल को फ़्लाउंडर भी कहा जाता है। इसके विकल्पों में हैलिबट और कॉड शामिल हैं; दोनों उतने ही स्वादिष्ट होते हैं।","अगर उपलब्ध हो, तो सूखी तुलसी की जगह 1/2 बड़ा चम्मच ताज़ी तुलसी का उपयोग करें। सबसे अच्छे स्वाद के लिए इसे मछली बेक करने से पहले नहीं, बल्कि पार्चमेंट खोलने के तुरंत बाद डालें।"],
["3 मांस","1-1/2 सब्जी, मध्यम पोटैशियम"]))
r.append(R(3848,"हवाईयन चिकन सलाद सैंडविच","द्वीपों का स्वाद चखने के लिए आपको हवाई जाने की ज़रूरत नहीं है। मिशिगन की DaVita आहार विशेषज्ञ लिंडा ने हवाईयन चिकन सलाद सैंडविच बनाया है, जो किडनी-अनुकूल, उच्च प्रोटीन वाला सैंडविच है और आप जहाँ भी हों, आपको उष्णकटिबंधीय मूड में पहुँचा सकता है।","4","1 कप चिकन सलाद, 1 टुकड़ा फ़्लैटब्रेड या टॉर्टिला",
["2 कप चिकन, पका हुआ","1 कप अनन्नास के छोटे टुकड़े","1/2 कप कम वसा वाला मेयोनेज़","1/2 कप हरी शिमला मिर्च","1/3 कप गाजर","1/2 छोटा चम्मच काली मिर्च","4 टुकड़े फ़्लैटब्रेड"],
["पके हुए चिकन को छोटे टुकड़ों में काटें।","अनन्नास का पानी निथार दें; शिमला मिर्च काटें और गाजर कद्दूकस करें।","सारी सामग्री एक कटोरे में मिलाएँ।","ठंडा होने तक फ्रिज में रखें।","चिकन सलाद को फ़्लैटब्रेड पर खुला परोसें या 6 इंच की आटे की टॉर्टिला में लपेटकर परोसें।"],
["कम या अधिक प्रोटीन वाले आहार के अनुसार मात्रा समायोजित करें।","चाहें तो ब्रेड की जगह मिले-जुले सलाद के पत्तों के ऊपर परोसें।","बचे हुए चिकन का उपयोग करने का यह बहुत अच्छा तरीका है।"],
["3 मांस","1 स्टार्च","1/2 फल, कम पोटैशियम","1/2 सब्जी, कम पोटैशियम"]))
save(1,r)
